const validContact=(method,value)=>{const v=String(value||'').trim();if(method==='email')return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v);if(method==='phone')return /^\+?[\d\s()\-]{8,25}$/.test(v)&&v.replace(/\D/g,'').length>=8&&v.replace(/\D/g,'').length<=16;if(method==='telegram')return /^@?[A-Za-z0-9_]{5,32}$/.test(v)||/^https:\/\/t\.me\/[A-Za-z0-9_]{5,32}\/?$/i.test(v);return false};
